// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum) public {
        vm.assume(newMinSum != initialMinSum);
        c.SetMinSum(initialMinSum);
        c.Initialized();
        uint256 before = c.MinSum();
        vm.prank(address(0xBEEF));
        try c.SetMinSum(newMinSum) {
            assertTrue(c.MinSum() == before, "MinSum must be immutable after initialization");
        } catch {
            assertTrue(c.MinSum() == before, "MinSum must be immutable after initialization");
        }
    }
}
